INSERT INTO `master_opt` VALUES (1, 'H001', 'Wereng Coklat', 'Nilaparvata lugens', 'Wereng Coklat, Brown Planthopper', 'Animalia', 'Arthropoda', 'Insecta', 'Hemiptera', 'Delphacidae', 'Nilaparvata', 'Tidak', 'Sangat Tinggi', 'BPTP Jawa Timur, Balitbangtan', 'Hama', 'Wereng coklat merupakan hama utama tanaman padi di Indonesia. Serangga ini mengisap cairan tanaman sehingga menyebabkan daun dan batang menguning (hopperburn). Populasi tinggi dapat menyebabkan puso (gagal panen total).', '/img/wereng.jpg', 10, 'Penggunaan varietas tahan wereng, pengendalian hayati dengan parasitoid, rotasi varietas, tidak menggunakan insektisida berlebihan', '2025-11-05 21:55:02', '2025-12-26 21:23:58');
INSERT INTO `master_opt` VALUES (2, 'H002', 'Penggerek Batang Padi', 'Scirpophaga incertulas', 'Sundep, Beluk', 'Animalia', 'Arthropoda', 'Insecta', 'Lepidoptera', 'Crambidae', 'Scirpophaga', 'Tidak', 'Tinggi', 'BPTP Jawa Timur', 'Hama', 'Larva menggerek batang padi menyebabkan sundep (fase vegetatif) atau beluk (fase generatif). Gejala sundep: tunas mati. Gejala beluk: malai hampa berwarna putih.', '', 5, 'Pengolahan tanah sempurna, pemasangan perangkap feromon, penggunaan parasitoid Trichogramma, aplikasi insektisida tepat waktu', '2025-11-05 21:55:02', '2025-12-26 21:23:58');
INSERT INTO `master_opt` VALUES (3, 'H003', 'Walang Sangit', 'Leptocorisa oratorius', 'Walang Sangit, Rice Bug', 'Animalia', 'Arthropoda', 'Insecta', 'Hemiptera', 'Alydidae', 'Leptocorisa', 'Tidak', 'Sedang', 'Balitbangtan', 'Hama', 'Serangga yang menghisap cairan bulir padi yang sedang mengisi. Menyebabkan bulir hampa atau beras menjadi berwarna hitam (spotty grain). Memiliki bau tidak sedap bila diganggu.', '', 2, 'Sanitasi lahan, pengendalian gulma, penggunaan insektisida kontak, pemanfaatan musuh alami', '2025-11-05 21:55:02', '2025-12-26 21:23:58');
INSERT INTO `master_opt` VALUES (4, 'P001', 'Blast (Blas)', 'Pyricularia oryzae', 'Blas, Potong Leher', 'Fungi', 'Ascomycota', 'Sordariomycetes', 'Magnaporthales', 'Pyriculariaceae', 'Pyricularia', 'Tidak', 'Sangat Tinggi', 'BB Padi', 'Penyakit', 'Penyakit jamur paling merusak pada padi. Menyerang daun (leaf blast), leher malai (neck blast), dan ruas batang. Gejala berupa bercak belah ketupat dengan pusat abu-abu.', '/img/blast.jpg', 0, 'Penggunaan varietas tahan, pemupukan berimbang, aplikasi fungisida (Trisiklazol, Isoprothiolane), pengaturan waktu tanam', '2025-11-05 21:55:02', '2025-12-26 21:23:58');
INSERT INTO `master_opt` VALUES (5, 'P002', 'Hawar Daun Bakteri', 'Xanthomonas oryzae pv. oryzae', 'Kresek, Bacterial Leaf Blight', 'Bacteria', 'Proteobacteria', 'Gammaproteobacteria', 'Xanthomonadales', 'Xanthomonadaceae', 'Xanthomonas', 'Tidak', 'Tinggi', 'BB Padi', 'Penyakit', 'Penyakit bakteri yang menyebabkan hawar pada daun padi. Gejala awal berupa bercak hijau kelabu di tepi daun yang meluas. Pada fase kresek, daun mengering seperti terbakar.', '', 0, 'Penggunaan varietas tahan, sanitasi lahan, pemupukan berimbang, tidak memupuk nitrogen berlebihan', '2025-11-05 21:55:02', '2025-12-26 21:23:58');
INSERT INTO `master_opt` VALUES (6, 'G001', 'Eceng Gondok', 'Eichhornia crassipes', 'Eceng Gondok, Water Hyacinth', 'Plantae', 'Tracheophyta', 'Liliopsida', 'Commelinales', 'Pontederiaceae', 'Eichhornia', 'Tidak', 'Tinggi', 'BPTP Jawa Timur', 'Gulma', 'Gulma air yang berkembang biak sangat cepat. Menyumbat saluran irigasi, mengurangi kadar oksigen air, dan bersaing dengan tanaman padi untuk sinar matahari.', '/img/brotowali.jpg', 0, 'Pengangkatan mekanis secara berkala, pengendalian biologi dengan kumbang Neochetina, herbisida selektif pada saluran air', '2025-11-05 21:55:02', '2025-12-26 21:23:58');
INSERT INTO `master_opt` VALUES (7, 'G002', 'Teki', 'Cyperus rotundus', 'Teki, Nut Grass', 'Plantae', 'Tracheophyta', 'Liliopsida', 'Cyperales', 'Cyperaceae', 'Cyperus', 'Tidak', 'Tinggi', 'Balitbangtan', 'Gulma', 'Gulma berdaun sempit yang sangat sulit dikendalikan karena memiliki umbi (nut) di dalam tanah. Berkompetisi kuat dengan tanaman padi untuk air, hara, dan cahaya.', '', 0, 'Pengolahan tanah berulang, pencabutan manual dengan umbi, herbisida pratumbuh, penyiraman genangan yang dalam', '2025-11-05 21:55:02', '2025-12-26 21:23:58');
INSERT INTO `master_opt` VALUES (11, 'G003', 'Rumput Sawah', 'Echinochloa crusgalli', 'Jawan, Barnyard Grass', 'Plantae', 'Tracheophyta', 'Liliopsida', 'Poales', 'Poaceae', 'Echinochloa', 'Tidak', 'Sedang', 'BPTP Jawa Timur', 'Gulma', 'Gulma rumput yang mirip tanaman padi saat muda. Sangat kompetitif terutama pada fase awal pertumbuhan padi. Dapat menurunkan hasil panen secara signifikan.', 'uploads/opt/2025/12/opt11_1766759335_e1e9f3192f51d738.png', 0, 'Penyiangan dini, herbisida pratumbuh, pengaturan air sawah yang tepat, rotasi tanam', '2025-12-14 21:26:10', '2025-12-26 21:28:55');
INSERT INTO `master_opt` VALUES (12, 'T001', 'Hama Test Admin', NULL, NULL, 'Animalia', NULL, NULL, NULL, NULL, NULL, 'Tidak', 'Sedang', NULL, 'Hama', 'Test description for Hama Test Admin', '', 100, '', '2025-12-26 17:57:52', '2025-12-26 17:57:52');
INSERT INTO `master_opt` VALUES (13, 'H004', 'Tikus Sawah', 'Rattus argentiventer', 'Tikus Sawah', 'Animalia', 'Chordata', 'Mammalia', 'Rodentia', 'Muridae', 'Rattus', 'Tidak', 'Sangat Tinggi', 'BPTP Jawa Timur', 'Hama', 'Hama vertebrata paling merusak pada pertanaman padi. Menyerang mulai dari persemaian hingga panen. Dapat menyebabkan kerusakan total area pertanaman.', NULL, 0, 'Gropyokan (berburu massal), pemasangan TBS (Trap Barrier System), penggunaan rodentisida, pembersihan sarang, tanam serempak', '2025-12-26 21:23:58', '2025-12-26 21:23:58');
INSERT INTO `master_opt` VALUES (14, 'H005', 'Ulat Grayak', 'Spodoptera litura', 'Ulat Grayak, Army Worm', 'Animalia', 'Arthropoda', 'Insecta', 'Lepidoptera', 'Noctuidae', 'Spodoptera', 'Tidak', 'Tinggi', 'Balitbangtan', 'Hama', 'Ulat yang menyerang daun padi secara berkelompok. Pada populasi tinggi dapat bermigrasi secara massal dan memakan habis daun tanaman.', NULL, 5, 'Pemasangan perangkap feromon, pengumpulan dan pemusnahan kelompok telur, penggunaan insektisida biologi (Bacillus thuringiensis)', '2025-12-26 21:23:58', '2025-12-26 21:23:58');
INSERT INTO `master_opt` VALUES (15, 'H006', 'Keong Mas', 'Pomacea canaliculata', 'Keong Mas, Golden Apple Snail', 'Animalia', 'Mollusca', 'Gastropoda', 'Architaenioglossa', 'Ampullariidae', 'Pomacea', 'Tidak', 'Tinggi', 'BPTP Jawa Timur', 'Hama', 'Moluska air tawar invasif yang memakan bibit padi muda. Sangat merusak pada fase pesemaian dan awal tanam. Berkembang biak cepat dengan telur berwarna merah muda.', NULL, 0, 'Pengumpulan manual dan telur, penggunaan itik sebagai predator alami, aplikasi moluskisida, pengaturan air sawah', '2025-12-26 21:23:58', '2025-12-26 21:23:58');
INSERT INTO `master_opt` VALUES (16, 'P003', 'Tungro', 'Rice Tungro Virus Complex', 'Tungro, Mentek', 'Virus', NULL, NULL, NULL, NULL, NULL, 'Tidak', 'Sangat Tinggi', 'Balitbangtan', 'Penyakit', 'Penyakit virus yang ditularkan oleh wereng hijau (Nephotettix virescens). Menyebabkan pertumbuhan kerdil, daun menguning hingga oranye, dan malai hampa.', NULL, 0, 'Penggunaan varietas tahan, pengendalian vektor wereng hijau, eradikasi tanaman terinfeksi, tanam serempak', '2025-12-26 21:23:58', '2025-12-26 21:23:58');
INSERT INTO `master_opt` VALUES (17, 'P004', 'Busuk Batang', 'Sclerotium oryzae', 'Busuk Batang', 'Fungi', 'Basidiomycota', 'Agaricomycetes', 'Atheliales', 'Atheliaceae', 'Sclerotium', 'Tidak', 'Sedang', 'BB Padi', 'Penyakit', 'Penyakit jamur yang menyerang pelepah daun dan batang bagian bawah. Menyebabkan batang mudah rebah dan malai tidak berkembang sempurna.', NULL, 0, 'Pengolahan tanah sempurna, pemupukan kalium yang cukup, drainase yang baik, aplikasi fungisida', '2025-12-26 21:23:58', '2025-12-26 21:23:58');
INSERT INTO `master_opt` VALUES (18, 'P005', 'Bercak Coklat', 'Bipolaris oryzae', 'Bercak Coklat, Brown Spot', 'Fungi', 'Ascomycota', 'Dothideomycetes', 'Pleosporales', 'Pleosporaceae', 'Bipolaris', 'Tidak', 'Sedang', 'BB Padi', 'Penyakit', 'Penyakit jamur dengan gejala bercak bulat lonjong berwarna coklat pada daun. Sering menyerang tanaman yang kekurangan unsur hara atau stres air.', NULL, 0, 'Pemupukan berimbang, penggunaan benih sehat, perlakuan benih dengan fungisida, pengairan yang baik', '2025-12-26 21:23:58', '2025-12-26 21:23:58');
INSERT INTO `master_opt` VALUES (19, 'G004', 'Genjer', 'Limnocharis flava', 'Genjer', 'Plantae', 'Tracheophyta', 'Liliopsida', 'Alismatales', 'Alismataceae', 'Limnocharis', 'Tidak', 'Rendah', 'Balitbangtan', 'Gulma', 'Gulma air yang dapat dimakan sebagai sayuran. Meskipun berkompetisi dengan padi, dampaknya relatif ringan dan tanaman ini memiliki nilai ekonomi sebagai pangan.', NULL, 0, 'Penyiangan manual untuk pemanfaatan sebagai sayuran, pengaturan tinggi air sawah', '2025-12-26 21:23:58', '2025-12-26 21:23:58');
