-- Table structure for feedback
-- ----------------------------
DROP TABLE IF EXISTS `feedback`;
CREATE TABLE `feedback`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `jenis_feedback` enum('bug','fitur_baru','peningkatan') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Jenis feedback: bug report, fitur baru, saran peningkatan',
  `judul` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Judul singkat feedback',
  `deskripsi` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Deskripsi detail masukan',
  `prioritas` enum('rendah','medium','tinggi') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'medium' COMMENT 'Tingkat prioritas feedback',
  `status` enum('diterima','dalam_proses','selesai','ditolak') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'diterima' COMMENT 'Status penanganan feedback',
  `attachment_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Path file pendukung (screenshot/dokumen)',
  `admin_notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'Catatan dari admin untuk feedback ini',
  `processed_by` int NULL DEFAULT NULL COMMENT 'ID admin yang memproses feedback',
  `processed_at` datetime NULL DEFAULT NULL COMMENT 'Waktu feedback diproses',
  `vote_count` int NULL DEFAULT 0 COMMENT 'Jumlah vote/dukungan dari user lain',
  `created_at` datetime NULL DEFAULT current_timestamp(),
  `updated_at` datetime NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `processed_by`(`processed_by` ASC) USING BTREE,
  INDEX `idx_feedback_status`(`status` ASC) USING BTREE,
  INDEX `idx_feedback_jenis`(`jenis_feedback` ASC) USING BTREE,
  INDEX `idx_feedback_prioritas`(`prioritas` ASC) USING BTREE,
  INDEX `idx_feedback_user`(`user_id` ASC) USING BTREE,
  INDEX `idx_feedback_vote`(`vote_count` ASC) USING BTREE,
  CONSTRAINT `feedback_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `feedback_ibfk_2` FOREIGN KEY (`processed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

