-- ----------------------------
-- Table structure for irrigation_adaptive_thresholds
-- ----------------------------
DROP TABLE IF EXISTS `irrigation_adaptive_thresholds`;
CREATE TABLE `irrigation_adaptive_thresholds`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `irigasi_id` int NOT NULL,
  `sensor_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'soil_moisture, water_ph, water_flow, etc.',
  `base_threshold_min` decimal(10, 2) NOT NULL COMMENT 'Base minimum threshold',
  `base_threshold_max` decimal(10, 2) NOT NULL COMMENT 'Base maximum threshold',
  `current_threshold_min` decimal(10, 2) NOT NULL COMMENT 'Weather-adjusted minimum',
  `current_threshold_max` decimal(10, 2) NOT NULL COMMENT 'Weather-adjusted maximum',
  `adjustment_factor` decimal(4, 2) NULL DEFAULT 1.00 COMMENT 'Current adjustment multiplier',
  `adjustment_reason` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Why adjustment was made',
  `last_adjusted_at` timestamp NULL DEFAULT NULL,
  `is_auto_adjust` tinyint(1) NULL DEFAULT 1 COMMENT 'Enable automatic adjustment',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `unique_irigasi_sensor`(`irigasi_id` ASC, `sensor_type` ASC) USING BTREE,
  INDEX `idx_auto_adjust`(`is_auto_adjust` ASC, `last_adjusted_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Adaptive thresholds that adjust based on weather conditions' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of irrigation_adaptive_thresholds
-- ----------------------------

-- ----------------------------
-- Table structure for irrigation_rule_logs
-- ----------------------------
DROP TABLE IF EXISTS `irrigation_rule_logs`;
CREATE TABLE `irrigation_rule_logs`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `rule_id` int NOT NULL,
  `irigasi_id` int NOT NULL,
  `triggered_at` timestamp NULL DEFAULT current_timestamp(),
  `conditions_snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'Sensor values at trigger time',
  `actions_executed` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT 'Actions that were executed',
  `execution_status` enum('success','partial','failed','skipped') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'success',
  `execution_duration_ms` int NULL DEFAULT NULL COMMENT 'Execution time in milliseconds',
  `error_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `weather_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT 'Weather conditions at trigger time',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_rule_triggered`(`rule_id` ASC, `triggered_at` ASC) USING BTREE,
  INDEX `idx_irigasi_triggered`(`irigasi_id` ASC, `triggered_at` ASC) USING BTREE,
  INDEX `idx_status`(`execution_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Execution logs for irrigation rules' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of irrigation_rule_logs
-- ----------------------------

-- ----------------------------
-- Table structure for irrigation_rules
-- ----------------------------
DROP TABLE IF EXISTS `irrigation_rules`;
CREATE TABLE `irrigation_rules`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `irigasi_id` int NOT NULL COMMENT 'Reference to irigasi table',
  `rule_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Human-readable rule name',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'Detailed rule description',
  `conditions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'Multi-condition rules in JSON format',
  `actions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'Actions to execute when conditions are met',
  `priority` int NULL DEFAULT 10 COMMENT 'Higher priority = evaluated first (1-100)',
  `is_active` tinyint(1) NULL DEFAULT 1 COMMENT '1=active, 0=inactive',
  `execution_count` int NULL DEFAULT 0 COMMENT 'Number of times rule was executed',
  `last_executed_at` timestamp NULL DEFAULT NULL COMMENT 'Last time rule was triggered',
  `cooldown_minutes` int NULL DEFAULT 60 COMMENT 'Minimum minutes between executions',
  `created_by` int NOT NULL COMMENT 'User ID who created the rule',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_irigasi_active`(`irigasi_id` ASC, `is_active` ASC) USING BTREE,
  INDEX `idx_active_priority`(`is_active` ASC, `priority` ASC) USING BTREE,
  INDEX `idx_last_executed`(`last_executed_at` ASC) USING BTREE,
  INDEX `idx_created_by`(`created_by` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Multi-condition rules for automated irrigation control' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of irrigation_rules
-- ----------------------------

