  `kabupaten` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `kabupaten_id` int NULL DEFAULT NULL,
  `kecamatan_id` int NULL DEFAULT NULL,
