  PRIMARY KEY (`id`) USING BTREE,
  INDEX `user_id`(`user_id` ASC) USING BTREE,
  INDEX `master_opt_id`(`master_opt_id` ASC) USING BTREE,
  INDEX `verified_by`(`verified_by` ASC) USING BTREE,
  INDEX `idx_laporan_kecamatan`(`kecamatan` ASC) USING BTREE,
  INDEX `idx_laporan_desa`(`desa` ASC) USING BTREE,
  INDEX `idx_laporan_kabupaten`(`kabupaten` ASC) USING BTREE,
  CONSTRAINT `laporan_hama_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `laporan_hama_ibfk_2` FOREIGN KEY (`master_opt_id`) REFERENCES `master_opt` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `laporan_hama_ibfk_3` FOREIGN KEY (`verified_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 129 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

