-- ----------------------------
-- Table structure for laporan_irigasi
-- ----------------------------
DROP TABLE IF EXISTS `laporan_irigasi`;
CREATE TABLE `laporan_irigasi`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `no_laporan` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `user_id` int NOT NULL COMMENT 'ID Pelapor',
  `nama_pelapor` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `kabupaten_id` int NULL DEFAULT NULL,
  `kecamatan_id` int NULL DEFAULT NULL,
  `desa_id` int NULL DEFAULT NULL,
  `nama_saluran` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `jenis_saluran` enum('Primer','Sekunder','Tersier') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `jenis_irigasi` enum('Teknis','Semi Teknis','Sederhana','Tadah Hujan') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `kondisi_fisik` enum('Baik','Rusak Ringan','Rusak Berat') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `debit_air` enum('Cukup','Kurang','Kering') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `luas_layanan` int NOT NULL COMMENT 'Dalam Hektar',
  `tanggal` date NOT NULL,
  `foto_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `latitude` decimal(10, 8) NULL DEFAULT NULL,
  `longitude` decimal(11, 8) NULL DEFAULT NULL,
  `catatan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `status` enum('Draf','Submitted','Diverifikasi','Ditolak') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'Draf',
  `status_perbaikan` enum('Dalam Perbaikan','Selesai Diperbaiki','Belum Ditangani') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `aksi_dilakukan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `verified_by` int NULL DEFAULT NULL,
  `verified_at` datetime NULL DEFAULT NULL,
  `catatan_verifikasi` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `created_at` datetime NULL DEFAULT current_timestamp(),
  `updated_at` datetime NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `no_laporan`(`no_laporan` ASC) USING BTREE,
  INDEX `idx_laporan_irigasi_user`(`user_id` ASC) USING BTREE,
  INDEX `idx_laporan_irigasi_status`(`status` ASC) USING BTREE,
  INDEX `idx_laporan_irigasi_wilayah`(`kabupaten_id` ASC, `kecamatan_id` ASC, `desa_id` ASC) USING BTREE,
  INDEX `idx_laporan_irigasi_verified`(`verified_by` ASC) USING BTREE,
  INDEX `idx_location_status`(`kabupaten_id` ASC, `kecamatan_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_tanggal_status`(`tanggal` ASC, `status` ASC) USING BTREE,
  INDEX `idx_user_tanggal`(`user_id` ASC, `tanggal` ASC) USING BTREE,
  INDEX `idx_verification_queue`(`status` ASC, `created_at` ASC) USING BTREE,
  CONSTRAINT `fk_laporan_irigasi_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_laporan_irigasi_verifier` FOREIGN KEY (`verified_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

