-- ----------------------------
-- Table structure for production_analytics
-- ----------------------------
DROP TABLE IF EXISTS `production_analytics`;
CREATE TABLE `production_analytics`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `periode` date NOT NULL COMMENT 'Periode analisis (awal musim)',
  `musim_tanam` enum('MT1','MT2','MT3') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `tahun` year NOT NULL,
  `lokasi_type` enum('kabupaten','kecamatan','desa','irigasi') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `lokasi_id` int NOT NULL,
  `lokasi_nama` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `total_luas_tanam` decimal(12, 2) NULL DEFAULT 0.00,
  `total_luas_panen` decimal(12, 2) NULL DEFAULT 0.00,
  `total_produksi` decimal(14, 2) NULL DEFAULT 0.00 COMMENT 'ton GKG',
  `avg_produktivitas` decimal(8, 2) NULL DEFAULT 0.00 COMMENT 'ton/ha',
  `avg_kadar_air` decimal(5, 2) NULL DEFAULT NULL,
  `grade_a_pct` decimal(5, 2) NULL DEFAULT 0.00,
  `grade_b_pct` decimal(5, 2) NULL DEFAULT 0.00,
  `grade_c_pct` decimal(5, 2) NULL DEFAULT 0.00,
  `grade_d_pct` decimal(5, 2) NULL DEFAULT 0.00,
  `total_beras` decimal(14, 2) NULL DEFAULT 0.00 COMMENT 'ton beras',
  `avg_rendemen` decimal(5, 2) NULL DEFAULT NULL,
  `avg_debit_air` decimal(8, 2) NULL DEFAULT NULL COMMENT 'L/s',
  `irrigation_days` int NULL DEFAULT 0,
  `irrigation_score` decimal(5, 2) NULL DEFAULT NULL COMMENT 'Skor 0-100',
  `total_curah_hujan` decimal(8, 2) NULL DEFAULT NULL COMMENT 'mm',
  `avg_temperature` decimal(5, 2) NULL DEFAULT NULL COMMENT 'Celsius',
  `rainy_days` int NULL DEFAULT 0,
  `weather_score` decimal(5, 2) NULL DEFAULT NULL,
  `pest_incidents` int NULL DEFAULT 0,
  `pest_severity_avg` decimal(5, 2) NULL DEFAULT NULL,
  `pest_risk_score` decimal(5, 2) NULL DEFAULT NULL,
  `correlation_irrigation` decimal(5, 4) NULL DEFAULT NULL COMMENT '-1 to 1',
  `correlation_weather` decimal(5, 4) NULL DEFAULT NULL,
  `correlation_pest` decimal(5, 4) NULL DEFAULT NULL,
  `overall_risk_score` decimal(5, 2) NULL DEFAULT NULL COMMENT '0-100',
  `risk_level` enum('low','medium','high','critical') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'low',
  `prev_period_produksi` decimal(14, 2) NULL DEFAULT NULL,
  `produksi_change_pct` decimal(6, 2) NULL DEFAULT NULL,
  `prev_period_produktivitas` decimal(8, 2) NULL DEFAULT NULL,
  `produktivitas_change_pct` decimal(6, 2) NULL DEFAULT NULL,
  `calculated_at` timestamp NULL DEFAULT current_timestamp(),
  `data_source_count` int NULL DEFAULT 0 COMMENT 'Jumlah record sumber',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_periode_lokasi`(`periode` ASC, `musim_tanam` ASC, `tahun` ASC, `lokasi_type` ASC, `lokasi_id` ASC) USING BTREE,
  INDEX `idx_musim_tahun`(`musim_tanam` ASC, `tahun` ASC) USING BTREE,
  INDEX `idx_risk_level`(`risk_level` ASC) USING BTREE,
  INDEX `idx_produktivitas`(`avg_produktivitas` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Tabel analitik agregat produksi gabah/beras dengan korelasi' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of production_analytics
-- ----------------------------

-- ----------------------------
-- Table structure for produksi_beras
-- ----------------------------
DROP TABLE IF EXISTS `produksi_beras`;
CREATE TABLE `produksi_beras`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `produksi_gabah_id` int NOT NULL COMMENT 'Relasi ke produksi_gabah',
  `tanggal_giling` date NOT NULL,
  `gabah_input` decimal(12, 2) NOT NULL COMMENT 'Jumlah gabah yang digiling (ton)',
  `beras_output` decimal(12, 2) NOT NULL COMMENT 'Jumlah beras hasil (ton)',
  `rendemen` decimal(5, 2) GENERATED ALWAYS AS (`beras_output` / nullif(`gabah_input`,0) * 100) STORED COMMENT 'Persen rendemen' NULL,
  `grade_beras` enum('Premium','Medium','Reguler') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'Medium',
  `broken_rice` decimal(5, 2) NULL DEFAULT NULL COMMENT 'Persen beras pecah',
  `harga_beras` decimal(12, 2) NULL DEFAULT NULL COMMENT 'Harga per kg (Rp)',
  `lokasi_penggilingan` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `keterangan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_produksi_gabah`(`produksi_gabah_id` ASC) USING BTREE,
  INDEX `idx_tanggal_giling`(`tanggal_giling` ASC) USING BTREE,
  INDEX `idx_rendemen`(`rendemen` ASC) USING BTREE,
  CONSTRAINT `fk_produksi_beras_gabah` FOREIGN KEY (`produksi_gabah_id`) REFERENCES `produksi_gabah` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Data produksi beras hasil penggilingan gabah' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of produksi_beras
-- ----------------------------

-- ----------------------------
-- Table structure for produksi_gabah
-- ----------------------------
DROP TABLE IF EXISTS `produksi_gabah`;
CREATE TABLE `produksi_gabah`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `unique_id` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Format: GBH-YYYYMMDD-XXXX',
  `musim_tanam` enum('MT1','MT2','MT3') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Musim Tanam 1/2/3',
  `tahun` year NOT NULL,
  `kabupaten_id` int NOT NULL,
  `kecamatan_id` int NOT NULL,
  `desa_id` int NULL DEFAULT NULL,
  `nama_lokasi` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `irigasi_id` int NULL DEFAULT NULL COMMENT 'Relasi ke tabel irigasi',
  `varietas` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Jenis varietas padi',
  `luas_tanam` decimal(10, 2) NOT NULL COMMENT 'Luas tanam dalam hektar',
  `luas_panen` decimal(10, 2) NOT NULL COMMENT 'Luas panen dalam hektar',
  `produksi_total` decimal(12, 2) NOT NULL COMMENT 'Produksi dalam ton GKG',
  `produktivitas` decimal(8, 2) GENERATED ALWAYS AS (`produksi_total` / nullif(`luas_panen`,0)) STORED COMMENT 'ton/ha' NULL,
  `kadar_air` decimal(5, 2) NULL DEFAULT NULL COMMENT 'Kadar air dalam persen',
  `grade_kualitas` enum('A','B','C','D') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'B' COMMENT 'Grade kualitas gabah',
  `harga_gabah` decimal(12, 2) NULL DEFAULT NULL COMMENT 'Harga per kg (Rp)',
  `foto` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `keterangan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `user_id` int NOT NULL,
  `verified_by` int NULL DEFAULT NULL,
  `verified_at` timestamp NULL DEFAULT NULL,
  `status` enum('draft','pending','verified','rejected') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'pending',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_unique_id`(`unique_id` ASC) USING BTREE,
  INDEX `idx_musim_tahun`(`musim_tanam` ASC, `tahun` ASC) USING BTREE,
  INDEX `idx_lokasi`(`kabupaten_id` ASC, `kecamatan_id` ASC, `desa_id` ASC) USING BTREE,
  INDEX `idx_irigasi`(`irigasi_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_user`(`user_id` ASC) USING BTREE,
  INDEX `idx_produktivitas`(`produktivitas` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Data produksi gabah per lokasi dan musim tanam' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of produksi_gabah
-- ----------------------------

