-- ----------------------------
-- Table structure for weather_alerts
-- ----------------------------
DROP TABLE IF EXISTS `weather_alerts`;
CREATE TABLE `weather_alerts`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `irigasi_id` int NOT NULL,
  `alert_type` enum('heavy_rain','drought','extreme_temp','high_wind','custom') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `severity` enum('info','warning','critical') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'info',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `weather_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT 'Weather conditions that triggered alert',
  `is_read` tinyint(1) NULL DEFAULT 0,
  `is_dismissed` tinyint(1) NULL DEFAULT 0,
  `valid_from` timestamp NULL DEFAULT current_timestamp(),
  `valid_until` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_irigasi_type`(`irigasi_id` ASC, `alert_type` ASC) USING BTREE,
  INDEX `idx_severity_read`(`severity` ASC, `is_read` ASC) USING BTREE,
  INDEX `idx_valid_until`(`valid_until` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Weather-based alerts for irrigation management' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of weather_alerts
-- ----------------------------

-- ----------------------------
-- Table structure for weather_cache
-- ----------------------------
DROP TABLE IF EXISTS `weather_cache`;
CREATE TABLE `weather_cache`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `location_key` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Format: lat_lng (e.g., -8.1723_113.7002)',
  `irigasi_id` int NULL DEFAULT NULL COMMENT 'Optional reference to specific irigasi',
  `kecamatan_id` int NULL DEFAULT NULL COMMENT 'Reference to kecamatan',
  `forecast_date` date NOT NULL,
  `precipitation_mm` decimal(8, 2) NULL DEFAULT NULL COMMENT 'Rainfall in mm',
  `precipitation_probability` int NULL DEFAULT NULL COMMENT 'Probability 0-100%',
  `temperature_max` decimal(5, 2) NULL DEFAULT NULL COMMENT 'Max temperature in Celsius',
  `temperature_min` decimal(5, 2) NULL DEFAULT NULL COMMENT 'Min temperature in Celsius',
  `temperature_avg` decimal(5, 2) NULL DEFAULT NULL COMMENT 'Average temperature in Celsius',
  `weather_code` int NULL DEFAULT NULL COMMENT 'WMO weather code',
  `weather_description` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Human-readable weather description',
  `humidity_avg` int NULL DEFAULT NULL COMMENT 'Average humidity 0-100%',
  `wind_speed_max` decimal(6, 2) NULL DEFAULT NULL COMMENT 'Max wind speed in km/h',
  `uv_index_max` decimal(4, 2) NULL DEFAULT NULL COMMENT 'UV index',
  `evapotranspiration` decimal(6, 2) NULL DEFAULT NULL COMMENT 'ET0 in mm',
  `source` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'open_meteo' COMMENT 'Data source',
  `raw_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT 'Raw API response for debugging',
  `fetched_at` timestamp NULL DEFAULT current_timestamp(),
  `expires_at` timestamp NULL DEFAULT NULL COMMENT 'Cache expiration time',
  `is_valid` tinyint(1) NULL DEFAULT 1 COMMENT '1=valid, 0=stale',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `unique_location_date`(`location_key` ASC, `forecast_date` ASC) USING BTREE,
  INDEX `idx_irigasi_date`(`irigasi_id` ASC, `forecast_date` ASC) USING BTREE,
  INDEX `idx_kecamatan_date`(`kecamatan_id` ASC, `forecast_date` ASC) USING BTREE,
  INDEX `idx_expires`(`expires_at` ASC) USING BTREE,
  INDEX `idx_valid`(`is_valid` ASC, `forecast_date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Cache for weather forecast data from Open-Meteo API' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of weather_cache
-- ----------------------------

-- ----------------------------
-- Table structure for wind_daily_summary
-- ----------------------------
DROP TABLE IF EXISTS `wind_daily_summary`;
CREATE TABLE `wind_daily_summary`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `tanggal` date NOT NULL,
  `lokasi` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `kode_wilayah` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `avg_speed` decimal(5, 2) NOT NULL COMMENT 'Rata-rata km/h',
  `max_speed` decimal(5, 2) NULL DEFAULT NULL COMMENT 'Maksimum km/h',
  `min_speed` decimal(5, 2) NULL DEFAULT NULL COMMENT 'Minimum km/h',
  `dominant_direction` smallint NULL DEFAULT NULL COMMENT 'Arah dominan dalam derajat',
  `dominant_direction_desc` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Arah dominan (N,NE,E,SE,S,SW,W,NW)',
  `beaufort_scale` tinyint NULL DEFAULT NULL COMMENT 'Skala Beaufort (0-12)',
  `beaufort_desc` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `spray_safe` tinyint(1) NULL DEFAULT 1 COMMENT '1=aman disemprot, 0=tidak disarankan',
  `pest_risk_level` enum('low','medium','high') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'low',
  `data_points` int NULL DEFAULT 0 COMMENT 'Jumlah data point',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_tanggal_lokasi`(`tanggal` ASC, `lokasi` ASC) USING BTREE,
  INDEX `idx_tanggal`(`tanggal` ASC) USING BTREE,
  INDEX `idx_spray_safe`(`tanggal` ASC, `spray_safe` ASC) USING BTREE,
  INDEX `idx_pest_risk`(`tanggal` ASC, `pest_risk_level` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Agregasi harian data kecepatan angin per lokasi' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of wind_daily_summary
-- ----------------------------

-- ----------------------------
-- Table structure for wind_pest_correlation
-- ----------------------------
DROP TABLE IF EXISTS `wind_pest_correlation`;
CREATE TABLE `wind_pest_correlation`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `tanggal` date NOT NULL,
  `lokasi` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `wind_direction` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `wind_speed_avg` decimal(5, 2) NULL DEFAULT NULL,
  `pest_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Jenis hama',
  `pest_spread_source` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Asal penyebaran',
  `correlation_score` decimal(4, 2) NULL DEFAULT NULL COMMENT 'Skor korelasi 0-1',
  `risk_level` enum('low','medium','high','critical') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'low',
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_tanggal`(`tanggal` ASC) USING BTREE,
  INDEX `idx_lokasi_pest`(`lokasi` ASC, `pest_type` ASC) USING BTREE,
  INDEX `idx_risk_level`(`risk_level` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Korelasi data angin dengan serangan hama' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of wind_pest_correlation
-- ----------------------------

-- ----------------------------
-- Table structure for wind_spray_recommendations
-- ----------------------------
DROP TABLE IF EXISTS `wind_spray_recommendations`;
CREATE TABLE `wind_spray_recommendations`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `tanggal` date NOT NULL,
  `waktu_mulai` time NULL DEFAULT NULL COMMENT 'Waktu mulai aman',
  `waktu_akhir` time NULL DEFAULT NULL COMMENT 'Waktu akhir aman',
  `lokasi` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `avg_speed_period` decimal(5, 2) NULL DEFAULT NULL COMMENT 'Rata-rata periode',
  `recommendation` enum('optimal','acceptable','not_recommended','dangerous') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `recommendation_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `beaufort_scale` tinyint NULL DEFAULT NULL,
  `direction_impact` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `pest_spread_warning` tinyint(1) NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_tanggal_lokasi`(`tanggal` ASC, `lokasi` ASC) USING BTREE,
  INDEX `idx_recommendation`(`tanggal` ASC, `recommendation` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Log rekomendasi penyemprotan berdasarkan kondisi angin' ROW_FORMAT = DYNAMIC;

